def gate(t):
    old = '!Array.isArray(req.body.ingredients) || req.body.ingredients.length > 100 || !req.body.ingredients.every(x => isText(x,1,500)) ||'
    new = '!Array.isArray(req.body.ingredients) || req.body.ingredients.length < 1 || req.body.ingredients.length > 100 || !req.body.ingredients.every(x => isText(x,1,500)) ||'
    assert old in t
    return t.replace(old, new, 1)
